public boolean use(Player player, game.GameProj gameProj) {
    if (currentCooldown > 0 || isCasting) {
        return false;
    }

    if (castTime > 0) {
        isCasting = true;
        castTimer = 0f;
        onCastStart(player, gameProj);
        return true;
    } else {
        execute(player, gameProj);
        currentCooldown = cooldown;
        return true;
    }
}
